pragma solidity ^0.8.9;

import "hardhat/console.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "./libraries/LongTermOrders.sol";
///@notice TWAMM -- https://www.paradigm.xyz/2021/07/twamm/
contract TWAMM is ERC20 {
    using LongTermOrdersLib for LongTermOrdersLib.LongTermOrders;
    using PRBMathUD60x18 for uint256;

    /// ---------------------------
    /// ------ AMM Parameters -----
    /// ---------------------------
    ///@notice tokens that can be traded in the AMM
    address public tokenA;
    address public tokenB;

    ///@notice fee for LP providers, 4 decimal places, i.e. 30 = 0.3%
    uint256 public constant LP_FEE = 30;

    ///@notice map token addresses to current amm reserves
    mapping(address => uint256) reserveMap;

    /// ---------------------------
    /// -----TWAMM Parameters -----
    /// ---------------------------

    ///@notice interval between blocks that are eligible for order expiry
    uint256 public orderBlockInterval;

    ///@notice data structure to handle long term orders
    LongTermOrdersLib.LongTermOrders internal longTermOrders;

    /// ---------------------------
    /// --------- Events ----------
    /// ---------------------------

    ///@notice An event emitted when initial liquidity is provided
    event InitialLiquidityProvided(
        address indexed addr,
        uint256 amountA,
        uint256 amountB
    );

    ///@notice An event emitted when liquidity is provided
    event LiquidityProvided(address indexed addr, uint256 lpTokens);

    ///@notice An event emitted when liquidity is removed
    event LiquidityRemoved(address indexed addr, uint256 lpTokens);

    ///@notice An event emitted when a swap from tokenA to tokenB is performed
    event SwapAToB(address indexed addr, uint256 amountAIn, uint256 amountBOut);

    ///@notice An event emitted when a swap from tokenB to tokenA is performed
    event SwapBToA(address indexed addr, uint256 amountBIn, uint256 amountAOut);

    ///@notice An event emitted when a long term swap from tokenA to tokenB is performed
    event LongTermSwapAToB(
        address indexed addr,
        uint256 amountAIn,
        uint256 orderId
    );

    ///@notice An event emitted when a long term swap from tokenB to tokenA is performed
    event LongTermSwapBToA(
        address indexed addr,
        uint256 amountBIn,
        uint256 orderId
    );

    ///@notice An event emitted when a long term swap is cancelled
    event CancelLongTermOrder(address indexed addr, uint256 orderId);

    ///@notice An event emitted when proceeds from a long term swap are withdrawm
    event WithdrawProceedsFromLongTermOrder(
        address indexed addr,
        uint256 orderId
    );

    constructor(
        string memory _name,
        string memory _symbol,
        address _tokenA,
        address _tokenB,
        uint256 _orderBlockInterval
    ) ERC20(_name, _symbol) {
        tokenA = _tokenA;
        tokenB = _tokenB;
        orderBlockInterval = _orderBlockInterval;
        longTermOrders.initialize(
            _tokenA,
            _tokenB,
            block.number,
            _orderBlockInterval
        );
    }

    // ///@notice provide  temporary approve function for user (msg.sender) to approve amount TokenA & B to this contract
    // function approveTokenAB(uint256 amountA, uint256 amountB)
    //     external
    // {
    //     ERC20(tokenA).approve(address(this), amountA); // this is self-approval, useless cause it's address(this) sending out this transaction
    //     ERC20(tokenB).approve(address(this), amountB); // the msg.sender approves address(this) to spend tokenB




    // }

    ///@notice provide initial liquidity to the amm. This sets the relative price between tokens
    function provideInitialLiquidity(uint256 amountA, uint256 amountB)
        external
    {
        require(
            totalSupply() == 0,
            "liquidity has already been provided, need to call provideLiquidity"
        );


        ERC20(tokenA).transferFrom(msg.sender, address(this), amountA);
        ERC20(tokenB).transferFrom(msg.sender, address(this), amountB);

        reserveMap[tokenA] = amountA;
        reserveMap[tokenB] = amountB;

        //initial LP amount is the geometric mean of supplied tokens
        uint256 lpAmount = amountA
            .fromUint()
            .sqrt()
            .mul(amountB.fromUint().sqrt())
            .toUint();
        _mint(msg.sender, lpAmount);

        emit InitialLiquidityProvided(msg.sender, amountA, amountB);
    }

    ///@notice provide liquidity to the AMM
    ///@param lpTokenAmount number of lp tokens to mint with new liquidity
    function provideLiquidity(uint256 lpTokenAmount) external {
        require(
            totalSupply() != 0,
            "no liquidity has been provided yet, need to call provideInitialLiquidity"
        );

        //execute virtual orders
        longTermOrders.executeVirtualOrdersUntilCurrentBlock(reserveMap);

        //the ratio between the number of underlying tokens and the number of lp tokens must remain invariant after mint
        uint256 amountAIn = (lpTokenAmount * reserveMap[tokenA]) /
            totalSupply();
        uint256 amountBIn = (lpTokenAmount * reserveMap[tokenB]) /
            totalSupply();

        ERC20(tokenA).transferFrom(msg.sender, address(this), amountAIn);
        ERC20(tokenB).transferFrom(msg.sender, address(this), amountBIn);

        reserveMap[tokenA] += amountAIn;
        reserveMap[tokenB] += amountBIn;

        _mint(msg.sender, lpTokenAmount);

        emit LiquidityProvided(msg.sender, lpTokenAmount);
    }

    ///@notice remove liquidity to the AMM
    ///@param lpTokenAmount number of lp tokens to burn
    function removeLiquidity(uint256 lpTokenAmount) external {
        require(
            lpTokenAmount <= totalSupply(),
            "not enough lp tokens available"
        );
        //execute virtual orders
        longTermOrders.executeVirtualOrdersUntilCurrentBlock(reserveMap);

        //the ratio between the number of underlying tokens and the number of lp tokens must remain invariant after burn
        uint256 amountAOut = (reserveMap[tokenA] * lpTokenAmount) /
            totalSupply();
        uint256 amountBOut = (reserveMap[tokenB] * lpTokenAmount) /
            totalSupply();

        ERC20(tokenA).transfer(msg.sender, amountAOut);
        ERC20(tokenB).transfer(msg.sender, amountBOut);

        reserveMap[tokenA] -= amountAOut;
        reserveMap[tokenB] -= amountBOut;

        _burn(msg.sender, lpTokenAmount);

        emit LiquidityRemoved(msg.sender, lpTokenAmount);
    }

    ///@notice swap a given amount of TokenA against embedded amm
    function swapFromAToB(uint256 amountAIn) external {
        uint256 amountBOut = performSwap(tokenA, tokenB, amountAIn);
        emit SwapAToB(msg.sender, amountAIn, amountBOut);
    }
    ///@notice create a long term order to swap from tokenA
    ///@param amountAIn total amount of token A to swap
    ///@param numberOfBlockIntervals number of block intervals over which to execute long term order
    function longTermSwapFromAToB(
        uint256 amountAIn,
        uint256 numberOfBlockIntervals
    ) external {
        uint256 orderId = longTermOrders.longTermSwapFromAToB(
            amountAIn,
            numberOfBlockIntervals,
            reserveMap
        );
        emit LongTermSwapAToB(msg.sender, amountAIn, orderId);
    }

    ///@notice swap a given amount of TokenB against embedded amm
    function swapFromBToA(uint256 amountBIn) external {
        uint256 amountAOut = performSwap(tokenB, tokenA, amountBIn);
        emit SwapBToA(msg.sender, amountBIn, amountAOut);
    }

    ///@notice create a long term order to swap from tokenB
    ///@param amountBIn total amount of tokenB to swap
    ///@param numberOfBlockIntervals number of block intervals over which to execute long term order
    function longTermSwapFromBToA(
        uint256 amountBIn,
        uint256 numberOfBlockIntervals
    ) external {
        uint256 orderId = longTermOrders.longTermSwapFromBToA(
            amountBIn,
            numberOfBlockIntervals,
            reserveMap
        );
        emit LongTermSwapBToA(msg.sender, amountBIn, orderId);
    }

    ///@notice stop the execution of a long term order
    function cancelLongTermSwap(uint256 orderId) external {
        longTermOrders.cancelLongTermSwap(orderId, reserveMap);
        emit CancelLongTermOrder(msg.sender, orderId);
    }

    ///@notice withdraw proceeds from a long term swap
    function withdrawProceedsFromLongTermSwap(uint256 orderId) external {
        longTermOrders.withdrawProceedsFromLongTermSwap(orderId, reserveMap);
        emit WithdrawProceedsFromLongTermOrder(msg.sender, orderId);
    }

    ///@notice private function which implements swap logic
    function performSwap(
        address from,
        address to,
        uint256 amountIn
    ) private returns (uint256 amountOutMinusFee) {
        require(amountIn > 0, "swap amount must be positive");

        //execute virtual orders
        longTermOrders.executeVirtualOrdersUntilCurrentBlock(reserveMap);

        //constant product formula
        uint256 amountOut = (reserveMap[to] * amountIn) /
            (reserveMap[from] + amountIn);
        //charge LP fee
        amountOutMinusFee = (amountOut * (10000 - LP_FEE)) / 10000;

        ERC20(from).transferFrom(msg.sender, address(this), amountIn);
        ERC20(to).transfer(msg.sender, amountOutMinusFee);

        reserveMap[from] += amountIn;
        reserveMap[to] -= amountOutMinusFee;
    }


    ///@notice get user orderIds
    function userIdsCheck(
        address userAddress
    ) external view returns (uint256[] memory) {
        return longTermOrders.orderIdMap[userAddress];
    }


    ///@notice get user orderIds
    function orderIdStatusCheck(
        uint256 orderId
    ) external view returns (bool) {
        return longTermOrders.orderIdStatusMap[orderId];
    }


    ///@notice get tokenA reserves
    function tokenAReserves() public view returns (uint256) {
        return reserveMap[tokenA];
    }

    ///@notice get tokenB reserves
    function tokenBReserves() public view returns (uint256) {
        return reserveMap[tokenB];
    }

    ///@notice convenience function to execute virtual orders. Note that this already happens
    ///before most interactions with the AMM
    function executeVirtualOrders() public {
        longTermOrders.executeVirtualOrdersUntilCurrentBlock(reserveMap);
    }
}
","keccak256":"0x8d1e2119ea5429c7f5464771e53ea47ad0c00bd01b7a7d9bcf15d962a8de6e33","license":"GPL-3.0-or-later"},"contracts/libraries/LongTermOrders.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.9;

import "hardhat/console.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "prb-math/contracts/PRBMathSD59x18.sol";
import "./OrderPool.sol";

///@notice This library handles the state and execution of long term orders.
library LongTermOrdersLib {
    using PRBMathSD59x18 for int256;
    using OrderPoolLib for OrderPoolLib.OrderPool;

    ///@notice information associated with a long term order
    struct Order {
        uint256 id;
        uint256 expirationBlock;
        uint256 saleRate;
        address owner;
        address sellTokenId;
        address buyTokenId;
    }

    ///@notice structure contains full state related to long term orders
    struct LongTermOrders {
        ///@notice minimum block interval between order expiries
        uint256 orderBlockInterval;
        ///@notice last virtual orders were executed immediately before this block
        uint256 lastVirtualOrderBlock;
        ///@notice token pair being traded in embedded amm
        address tokenA;
        address tokenB;
        ///@notice mapping from token address to pool that is selling that token
        ///we maintain two order pools, one for each token that is tradable in the AMM
        mapping(address => OrderPoolLib.OrderPool) OrderPoolMap;
        ///@notice incrementing counter for order ids
        uint256 orderId;
        ///@notice mapping from order ids to Orders
        mapping(uint256 => Order) orderMap;

        ///@notice mapping from account address to its corresponding list of order ids
        mapping(address => uint256[]) orderIdMap;

        ///@notice mapping from order id to its status (false for nonactive true for active)
        mapping(uint256 => bool) orderIdStatusMap;

    }

    ///@notice initialize state
    function initialize(
        LongTermOrders storage self,
        address tokenA,
        address tokenB,
        uint256 lastVirtualOrderBlock,
        uint256 orderBlockInterval
    ) internal {
        self.tokenA = tokenA;
        self.tokenB = tokenB;
        self.lastVirtualOrderBlock = lastVirtualOrderBlock;
        self.orderBlockInterval = orderBlockInterval;
    }

    ///@notice swap token A for token B. Amount represents total amount being sold, numberOfBlockIntervals determines when order expires
    function longTermSwapFromAToB(
        LongTermOrders storage self,
        uint256 amountA,
        uint256 numberOfBlockIntervals,
        mapping(address => uint256) storage reserveMap
    ) internal returns (uint256) {
        return
            performLongTermSwap(
                self,
                self.tokenA,
                self.tokenB,
                amountA,
                numberOfBlockIntervals,
                reserveMap
            );
    }

    ///@notice swap token B for token A. Amount represents total amount being sold, numberOfBlockIntervals determines when order expires
    function longTermSwapFromBToA(
        LongTermOrders storage self,
        uint256 amountB,
        uint256 numberOfBlockIntervals,
        mapping(address => uint256) storage reserveMap
    ) internal returns (uint256) {
        return
            performLongTermSwap(
                self,
                self.tokenB,
                self.tokenA,
                amountB,
                numberOfBlockIntervals,
                reserveMap
            );
    }

    ///@notice adds long term swap to order pool
    function performLongTermSwap(
        LongTermOrders storage self,
        address from,
        address to,
        uint256 amount,
        uint256 numberOfBlockIntervals,
        mapping(address => uint256) storage reserveMap
    ) private returns (uint256) {
        //update virtual order state
        executeVirtualOrdersUntilCurrentBlock(self, reserveMap);

        // transfer sale amount to contract
        ERC20(from).transferFrom(msg.sender, address(this), amount);

        //determine the selling rate based on number of blocks to expiry and total amount
        uint256 currentBlock = block.number;
        uint256 lastExpiryBlock = currentBlock -
            (currentBlock % self.orderBlockInterval);
        uint256 orderExpiry = self.orderBlockInterval *
            (numberOfBlockIntervals + 1) +
            lastExpiryBlock;
        uint256 sellingRate = amount / (orderExpiry - currentBlock);

        //add order to correct pool
        OrderPoolLib.OrderPool storage OrderPool = self.OrderPoolMap[from];
        OrderPool.depositOrder(self.orderId, sellingRate, orderExpiry);

        //add to order map
        self.orderMap[self.orderId] = Order(
            self.orderId,
            orderExpiry,
            sellingRate,
            msg.sender,
            from,
            to
        );

        // add user to orderId mapping list content 
        self.orderIdMap[msg.sender].push(self.orderId);

        self.orderIdStatusMap[self.orderId] = true;

        return self.orderId++;
    }

    // ///@notice remove orderId from user orderIdMap after the order is physically cancelled
    // function removeOrderId(
    //     LongTermOrders storage self,
    //     uint256 orderId,
    //     address account
    // ) internal view {
    //     uint256[] memory orderIdList = self.orderIdMap[account];
    //     require(orderIdList.length > 0, "this sender doesn't have long term swap orders");
        // if (orderIdList.length == 1) {
        //     delete orderIdList[0];
        // }
        // uint l = 0;
        // uint r = orderIdList.length - 1;
        // uint m ;
        // while (l < r) {
        //    m = uint(l + r / 2);
        //    if ( orderIdList[m] < orderId) {
        //         l = m + 1;
        //    } else if ( orderIdList[m] > orderId) {
        //        r = m - 1;
        //    } else {
        //        delete orderIdList[m];
        //    }
        // }


    // }

    ///@notice cancel long term swap, pay out unsold tokens and well as purchased tokens
    function cancelLongTermSwap(
        LongTermOrders storage self,
        uint256 orderId,
        mapping(address => uint256) storage reserveMap
    ) internal {
        //update virtual order state
        executeVirtualOrdersUntilCurrentBlock(self, reserveMap);

        Order storage order = self.orderMap[orderId];
        require(order.owner == msg.sender, "sender must be order owner");

        OrderPoolLib.OrderPool storage OrderPool = self.OrderPoolMap[
            order.sellTokenId
        ];
        (uint256 unsoldAmount, uint256 purchasedAmount) = OrderPool.cancelOrder(
            orderId
        );

        require(
            unsoldAmount > 0 || purchasedAmount > 0,
            "no proceeds to withdraw"
        );
        //transfer to owner
        ERC20(order.buyTokenId).transfer(msg.sender, purchasedAmount);
        ERC20(order.sellTokenId).transfer(msg.sender, unsoldAmount);


        // delete orderId from account list
        // removeOrderId(self, orderId, msg.sender);
        self.orderIdStatusMap[orderId] = false;
    }

    ///@notice withdraw proceeds from a long term swap (can be expired or ongoing)
    function withdrawProceedsFromLongTermSwap(
        LongTermOrders storage self,
        uint256 orderId,
        mapping(address => uint256) storage reserveMap
    ) internal {
        //update virtual order state
        executeVirtualOrdersUntilCurrentBlock(self, reserveMap);

        Order storage order = self.orderMap[orderId];
        require(order.owner == msg.sender, "sender must be order owner");

        OrderPoolLib.OrderPool storage OrderPool = self.OrderPoolMap[
            order.sellTokenId
        ];
        uint256 proceeds = OrderPool.withdrawProceeds(orderId);

        require(proceeds > 0, "no proceeds to withdraw");
        //transfer to owner
        ERC20(order.buyTokenId).transfer(msg.sender, proceeds);

        // delete orderId from account list
        // removeOrderId(self, orderId, msg.sender);
        self.orderIdStatusMap[orderId] = false;
    }

    ///@notice executes all virtual orders between current lastVirtualOrderBlock and blockNumber
    //also handles orders that expire at end of final block. This assumes that no orders expire inside the given interval
    function executeVirtualTradesAndOrderExpiries(
        LongTermOrders storage self,
        mapping(address => uint256) storage reserveMap,
        uint256 blockNumber
    ) private {
        //amount sold from virtual trades
        uint256 blockNumberIncrement = blockNumber - self.lastVirtualOrderBlock;
        uint256 tokenASellAmount = self
            .OrderPoolMap[self.tokenA]
            .currentSalesRate * blockNumberIncrement;
        uint256 tokenBSellAmount = self
            .OrderPoolMap[self.tokenB]
            .currentSalesRate * blockNumberIncrement;

        //initial amm balance
        uint256 tokenAStart = reserveMap[self.tokenA];
        uint256 tokenBStart = reserveMap[self.tokenB];

        //updated balances from sales
        (
            uint256 tokenAOut,
            uint256 tokenBOut,
            uint256 ammEndTokenA,
            uint256 ammEndTokenB
        ) = computeVirtualBalances(
                tokenAStart,
                tokenBStart,
                tokenASellAmount,
                tokenBSellAmount
            );

        //update balances reserves
        reserveMap[self.tokenA] = ammEndTokenA;
        reserveMap[self.tokenB] = ammEndTokenB;

        //distribute proceeds to pools
        OrderPoolLib.OrderPool storage OrderPoolA = self.OrderPoolMap[
            self.tokenA
        ];
        OrderPoolLib.OrderPool storage OrderPoolB = self.OrderPoolMap[
            self.tokenB
        ];

        OrderPoolA.distributePayment(tokenBOut);
        OrderPoolB.distributePayment(tokenAOut);

        //handle orders expiring at end of interval
        OrderPoolA.updateStateFromBlockExpiry(blockNumber);
        OrderPoolB.updateStateFromBlockExpiry(blockNumber);

        //update last virtual trade block
        self.lastVirtualOrderBlock = blockNumber;
    }

    ///@notice executes all virtual orders until current block is reached.
    function executeVirtualOrdersUntilCurrentBlock(
        LongTermOrders storage self,
        mapping(address => uint256) storage reserveMap
    ) internal {
        uint256 nextExpiryBlock = self.lastVirtualOrderBlock -
            (self.lastVirtualOrderBlock % self.orderBlockInterval) +
            self.orderBlockInterval;
        //iterate through blocks eligible for order expiries, moving state forward
        while (nextExpiryBlock < block.number) {
            executeVirtualTradesAndOrderExpiries(
                self,
                reserveMap,
                nextExpiryBlock
            );
            nextExpiryBlock += self.orderBlockInterval;
        }
        //finally, move state to current block if necessary
        if (self.lastVirtualOrderBlock != block.number) {
            executeVirtualTradesAndOrderExpiries(
                self,
                reserveMap,
                block.number
            );
        }
    }

    ///@notice computes the result of virtual trades by the token pools
    function computeVirtualBalances(
        uint256 tokenAStart,
        uint256 tokenBStart,
        uint256 tokenAIn,
        uint256 tokenBIn
    )
        private
        pure
        returns (
            uint256 tokenAOut,
            uint256 tokenBOut,
            uint256 ammEndTokenA,
            uint256 ammEndTokenB
        )
    {
        //if no tokens are sold to the pool, we don't need to execute any orders
        if (tokenAIn == 0 && tokenBIn == 0) {
            tokenAOut = 0;
            tokenBOut = 0;
            ammEndTokenA = tokenAStart;
            ammEndTokenB = tokenBStart;
        }
        //in the case where only one pool is selling, we just perform a normal swap
        else if (tokenAIn == 0) {
            //constant product formula
            tokenAOut = (tokenAStart * tokenBIn) / (tokenBStart + tokenBIn);
            tokenBOut = 0;
            ammEndTokenA = tokenAStart - tokenAOut;
            ammEndTokenB = tokenBStart + tokenBIn;
        } else if (tokenBIn == 0) {
            tokenAOut = 0;
            //contant product formula
            tokenBOut = (tokenBStart * tokenAIn) / (tokenAStart + tokenAIn);
            ammEndTokenA = tokenAStart + tokenAIn;
            ammEndTokenB = tokenBStart - tokenBOut;
        }
        //when both pools sell, we use the TWAMM formula
        else {
            //signed, fixed point arithmetic
            int256 aIn = int256(tokenAIn).fromInt();
            int256 bIn = int256(tokenBIn).fromInt();
            int256 aStart = int256(tokenAStart).fromInt();
            int256 bStart = int256(tokenBStart).fromInt();
            int256 k = aStart.mul(bStart);

            int256 c = computeC(aStart, bStart, aIn, bIn);
            int256 endA = computeAmmEndTokenA(aIn, bIn, c, k, aStart, bStart);
            int256 endB = aStart.div(endA).mul(bStart);

            int256 outA = aStart + aIn - endA;
            int256 outB = bStart + bIn - endB;

            return (
                uint256(outA.toInt()),
                uint256(outB.toInt()),
                uint256(endA.toInt()),
                uint256(endB.toInt())
            );
        }
    }

    //helper function for TWAMM formula computation, helps avoid stack depth errors
    function computeC(
        int256 tokenAStart,
        int256 tokenBStart,
        int256 tokenAIn,
        int256 tokenBIn
    ) private pure returns (int256 c) {
        int256 c1 = tokenAStart.sqrt().mul(tokenBIn.sqrt());
        int256 c2 = tokenBStart.sqrt().mul(tokenAIn.sqrt());
        int256 cNumerator = c1 - c2;
        int256 cDenominator = c1 + c2;
        c = cNumerator.div(cDenominator);
    }

    //helper function for TWAMM formula computation, helps avoid stack depth errors
    function computeAmmEndTokenA(
        int256 tokenAIn,
        int256 tokenBIn,
        int256 c,
        int256 k,
        int256 aStart,
        int256 bStart
    ) private pure returns (int256 ammEndTokenA) {
        //rearranged for numerical stability
        int256 eNumerator = PRBMathSD59x18
            .fromInt(4)
            .mul(tokenAIn)
            .mul(tokenBIn)
            .sqrt();
        int256 eDenominator = aStart.sqrt().mul(bStart.sqrt()).inv();
        int256 exponent = eNumerator.mul(eDenominator).exp();
        int256 fraction = (exponent + c).div(exponent - c);
        int256 scaling = k.div(tokenBIn).sqrt().mul(tokenAIn.sqrt());
        ammEndTokenA = fraction.mul(scaling);
    }
}
